import json, collections
data = json.load(open('analysis.json', encoding='utf-8'))

print("=== TOTAL PAGES:", len(data))

print("\n=== Missing title ===")
for k,v in data.items():
    if not v['title']: print(k)

print("\n=== Missing description ===")
for k,v in data.items():
    if not v['desc']: print(k)

print("\n=== title length >70 ===")
for k,v in data.items():
    if v['title_len']>70: print(f"{k} ({v['title_len']}): {v['title']}")

print("\n=== desc length issues (0 or >160 or <50) ===")
for k,v in data.items():
    if v['desc_len']==0: continue
    if v['desc_len']>160 or v['desc_len']<50:
        print(f"{k} ({v['desc_len']}): {v['desc']}")

print("\n=== Duplicate titles ===")
titles = collections.defaultdict(list)
for k,v in data.items():
    if v['title']: titles[v['title']].append(k)
for t,ks in titles.items():
    if len(ks)>1: print(f"'{t}' -> {ks}")

print("\n=== Duplicate descriptions ===")
descs = collections.defaultdict(list)
for k,v in data.items():
    if v['desc']: descs[v['desc']].append(k)
for t,ks in descs.items():
    if len(ks)>1: print(f"'{t[:50]}...' -> {ks}")

print("\n=== h1 count != 1 ===")
for k,v in data.items():
    if v['h1_count']!=1: print(f"{k}: count={v['h1_count']} -> {v['h1s']}")

print("\n=== missing canonical ===")
for k,v in data.items():
    if not v['canonical']: print(k)

print("\n=== missing viewport ===")
for k,v in data.items():
    if not v['viewport']: print(k)

print("\n=== missing favicon ===")
for k,v in data.items():
    if not v['favicon']: print(k)

print("\n=== missing OGP (title/desc/image) ===")
for k,v in data.items():
    missing=[]
    if not v['og_title']: missing.append('og:title')
    if not v['og_desc']: missing.append('og:desc')
    if not v['og_image']: missing.append('og:image')
    if missing: print(f"{k}: {missing}")

print("\n=== robots noindex pages ===")
for k,v in data.items():
    if v['robots'] and 'noindex' in v['robots'].lower():
        print(f"{k}: {v['robots']}")
EOF

